content.text:
Brief:
Un long cahier des charges pour un jeu de phare en plusieurs niveaux. Le joueur est le gardien d'un vieux phare sur une côte rocheuse, et chaque niveau se passe pendant une nuit de tempête. Des bateaux approchent depuis le large, et le joueur doit tourner le faisceau du phare en glissant le doigt autour de la tour pour éclairer chaque bateau avant qu'il ne touche les rochers. Un bateau éclairé assez longtemps trouve le chenal et rentre au port, ce qui compte pour l'objectif du niveau. Quand tous les bateaux d'une nuit sont rentrés, le niveau est gagné et une courte carte annonce la nuit suivante. Les nuits suivantes amènent plus de bateaux, du brouillard qui cache une partie de la mer et des vagues qui déplacent les bateaux. Si un bateau touche les rochers, la partie est perdue, avec un message qui dit quel bateau a coulé et un bouton pour rejouer la nuit. Je voudrais une mer bleu nuit, un faisceau jaune pâle et des bateaux rouges, dessinés simplement avec des formes plates. Le texte du jeu doit rester en français, avec le numéro de la nuit affiché en haut de l'écran pendant toute la partie.

Plan:
{"gameType":"stage-clear","input":"drag-follow","lang":"fr","loop":"Glissez le doigt autour du phare pour tourner le faisceau et éclairer chaque bateau assez longtemps pour qu'il rentre au port. Une nuit est gagnée quand tous les bateaux sont rentrés ; un bateau qui touche les rochers termine la partie.","slug":"le-phare-des-naufrages","style":"paper-cut","title":"Le Phare des Naufrages"}

Game source (line-numbered):
1| <!doctype html>
2| <html lang="fr">
3| <head>
4| <meta charset="utf-8">
5| <meta name="viewport" content="width=device-width, initial-scale=1">
6| <title>Le Phare des Naufrages</title>
7| <style>
8|   html, body {
9|     margin: 0; padding: 0; overflow: hidden;
10|     background: #f4ecd8;
11|     width: 100%; height: 100%;
12|     touch-action: none;
13|     font-family: -apple-system, "Segoe UI", Roboto, Arial, sans-serif;
14|   }
15|   #stage {
16|     position: fixed; inset: 0;
17|     width: 100vw; height: 100dvh;
18|     display: block;
19|   }
20|   #hint {
21|     position: fixed;
22|     left: 50%; top: 8px;
23|     transform: translateX(-50%);
24|     color: #3d405b;
25|     font-weight: 700;
26|     font-size: 14px;
27|     pointer-events: none;
28|     user-select: none;
29|     text-align: center;
30|   }
31| </style>
32| </head>
33| <body>
34| <canvas id="stage"></canvas>
35| <script>
36| // ---- Bridge helper (verbatim) ----
37| const CARTRIDGE = {
38|   send(type, payload = {}) {
39|     window.parent.postMessage(
40|       { source: "cartridge", v: 1, type, payload },
41|       "*",
42|     );
43|   },
44| };
45| </script>
46| <script>
47| (function(){
48|   const canvas = document.getElementById('stage');
49|   const ctx = canvas.getContext('2d');
50|   let W = 0, H = 0, DPR = 1;
51| 
52|   function resize() {
53|     DPR = window.devicePixelRatio || 1;
54|     W = window.innerWidth;
55|     H = window.innerHeight;
56|     canvas.width = Math.round(W * DPR);
57|     canvas.height = Math.round(H * DPR);
58|     canvas.style.width = W + 'px';
59|     canvas.style.height = H + 'px';
60|     ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
61|   }
62|   window.addEventListener('resize', resize);
63|   resize();
64| 
65|   // ---- seeded jitter for paper-cut edges ----
66|   let seedVal = 1234567;
67|   function rand() {
68|     seedVal = (seedVal * 1103515245 + 12345) & 0x7fffffff;
69|     return (seedVal % 1000) / 1000;
70|   }
71|   function jitter(v, amt) { return v + (rand() - 0.5) * amt; }
72| 
73|   const PAL = {
74|     bg: '#f4ecd8',
75|     layer: '#e07a5f',
76|     accent: '#3d405b',
77|     highlight: '#81b29a'
78|   };
79| 
80|   // ---- Game state ----
81|   let state = 'title'; // title, playing, stageclear, win, lose
82|   let paused = false;
83|   let stage = 0;
84|   let score = 0;
85|   let beamAngle = 0; // radians, pointing direction of beam
86|   let beamTarget = 0;
87|   let held = false;
88|   let graceTimer = 0;
89|   let stageGoalText = '';
90|   let boats = [];
91|   let lastTime = performance.now();
92|   let bootSent = false;
93| 
94|   const STAGES = [
95|     { boatCount: 1, boatSpeed: 0.10, needLight: 2.0, rockChance: 0.0 },
96|     { boatCount: 2, boatSpeed: 0.13, needLight: 2.2, rockChance: 0.15 },
97|     { boatCount: 3, boatSpeed: 0.16, needLight: 2.4, rockChance: 0.25 },
98|     { boatCount: 3, boatSpeed: 0.20, needLight: 2.6, rockChance: 0.35 },
99|     { boatCount: 4, boatSpeed: 0.24, needLight: 2.8, rockChance: 0.4 }
100|   ];
101| 
102|   function cx() { return W / 2; }
103|   function cy() { return H / 2; }
104|   function lighthouseRadius() { return Math.min(W, H) * 0.09; }
105|   function worldRadius() { return Math.min(W, H) * 0.46; }
106| 
107|   function toCanvas(evt) {
108|     const rect = canvas.getBoundingClientRect();
109|     return {
110|       x: (evt.clientX - rect.left),
111|       y: (evt.clientY - rect.top)
112|     };
113|   }
114| 
115|   function angleTo(px, py) {
116|     return Math.atan2(py - cy(), px - cx());
117|   }
118| 
119|   // ---- Boats ----
120|   function makeBoat(cfg, idx) {
121|     const angle = rand() * Math.PI * 2;
122|     const dist = worldRadius() * (0.85 + rand() * 0.15);
123|     const isRock = rand() < cfg.rockChance && idx > 0;
124|     return {
125|       angle: angle,
126|       dist: dist,
127|       speed: cfg.boatSpeed * (0.85 + rand() * 0.3),
128|       lit: 0,
129|       needLight: cfg.needLight,
130|       saved: false,
131|       wrecked: false,
132|       wobble: rand() * Math.PI * 2,
133|       seedA: rand(), seedB: rand(), seedC: rand()
134|     };
135|   }
136| 
137|   function buildStage(n) {
138|     const cfg = STAGES[n - 1];
139|     boats = [];
140|     for (let i = 0; i < cfg.boatCount; i++) {
141|       boats.push(makeBoat(cfg, i));
142|     }
143|     stageGoalText = 'Nuit ' + n + ' — Guidez ' + cfg.boatCount + ' bateau' + (cfg.boatCount>1?'x':'') + ' au port';
144|     graceTimer = 2.5; // seconds of grace
145|     score = 0;
146|     CARTRIDGE.send('score', { value: score });
147|   }
148| 
149|   function enterStage(next) {
150|     stage = next;
151|     buildStage(stage);
152|     CARTRIDGE.send('level', { index: stage });
153|     state = 'playing';
154|   }
155| 
156|   function onGoalMet() {
157|     if (stage === STAGES.length) {
158|       state = 'win';
159|       CARTRIDGE.send('end', { reason: 'win', value: score });
160|     } else {
161|       state = 'stageclear';
162|       stageClearTimer = 1.6;
163|     }
164|   }
165| 
166|   function onStageFailed() {
167|     state = 'lose';
168|     CARTRIDGE.send('end', { reason: 'lose', value: score });
169|   }
170| 
171|   let stageClearTimer = 0;
172| 
173|   function backToTitle() {
174|     state = 'title';
175|     paused = false;
176|     stage = 0;
177|     score = 0;
178|     boats = [];
179|   }
180| 
181|   // ---- Input (drag-follow style) ----
182|   let pointerId = null;
183|   canvas.addEventListener('pointerdown', (event) => {
184|     const p = toCanvas(event);
185|     const dx = p.x - cx(), dy = p.y - cy();
186|     const dist = Math.hypot(dx, dy);
187|     // allow grabbing anywhere for steering the beam
188|     held = true;
189|     pointerId = event.pointerId;
190|     canvas.setPointerCapture(event.pointerId);
191|     if (state === 'title') {
192|       startGame();
193|     } else if (state === 'playing') {
194|       beamTarget = angleTo(p.x, p.y);
195|     } else if (state === 'lose' || state === 'win') {
196|       backToTitle();
197|     }
198|   });
199|   canvas.addEventListener('pointermove', (event) => {
200|     if (held && state === 'playing') {
201|       const p = toCanvas(event);
202|       beamTarget = angleTo(p.x, p.y);
203|     }
204|   });
205|   function release(event) {
206|     held = false;
207|     pointerId = null;
208|   }
209|   canvas.addEventListener('pointerup', release);
210|   canvas.addEventListener('pointercancel', release);
211| 
212|   function startGame() {
213|     CARTRIDGE.send('start');
214|     enterStage(1);
215|   }
216| 
217|   // ---- Update ----
218|   function shortestAngleDiff(a, b) {
219|     let d = (b - a) % (Math.PI * 2);
220|     if (d > Math.PI) d -= Math.PI * 2;
221|     if (d < -Math.PI) d += Math.PI * 2;
222|     return d;
223|   }
224| 
225|   function update(dt) {
226|     if (paused) return;
227| 
228|     // ease beam toward target
229|     const diff = shortestAngleDiff(beamAngle, beamTarget);
230|     beamAngle += diff * Math.min(1, dt * 6);
231| 
232|     if (state === 'stageclear') {
233|       stageClearTimer -= dt;
234|       if (stageClearTimer <= 0) enterStage(stage + 1);
235|       return;
236|     }
237| 
238|     if (state !== 'playing') return;
239| 
240|     if (graceTimer > 0) graceTimer -= dt;
241| 
242|     const beamWidth = 0.42; // half-angle of cone in radians
243| 
244|     let allSaved = true;
245|     for (const boat of boats) {
246|       if (boat.saved || boat.wrecked) continue;
247|       allSaved = false;
248| 
249|       // move boat inward slowly, wobbling angle
250|       boat.wobble += dt * 0.5;
251|       boat.dist -= boat.speed * 22 * dt;
252| 
253|       if (boat.dist < lighthouseRadius() * 1.3) {
254|         boat.dist = lighthouseRadius() * 1.3;
255|       }
256| 
257|       // check if lit
258|       const diffA = Math.abs(shortestAngleDiff(beamAngle, boat.angle));
259|       const isLit = diffA < beamWidth;
260|       if (isLit) {
261|         boat.lit += dt;
262|         if (boat.lit >= boat.needLight) {
263|           boat.saved = true;
264|           score += 10;
265|           CARTRIDGE.send('score', { value: score });
266|         }
267|       } else {
268|         boat.lit = Math.max(0, boat.lit - dt * 0.4);
269|       }
270| 
271|       // danger: if boat reaches inner rocks without being saved and grace passed
272|       if (graceTimer <= 0 && boat.dist <= lighthouseRadius() * 1.35 && !boat.saved) {
273|         boat.wrecked = true;
274|         onStageFailed();
275|         return;
276|       }
277|     }
278| 
279|     const stillActive = boats.some(b => !b.saved && !b.wrecked);
280|     if (!stillActive) {
281|       onGoalMet();
282|     }
283|   }
284| 
285|   // ---- Draw helpers: paper-cut primitives ----
286|   function shadowedPath(drawFn, fillColor) {
287|     ctx.save();
288|     ctx.shadowColor = 'rgba(61,64,91,0.35)';
289|     ctx.shadowBlur = 6;
290|     ctx.shadowOffsetY = 3;
291|     ctx.fillStyle = fillColor;
292|     drawFn();
293|     ctx.restore();
294|   }
295| 
296|   function jitterPolygon(points, amt) {
297|     return points.map(p => [jitter(p[0], amt), jitter(p[1], amt)]);
298|   }
299| 
300|   function drawPolygon(points) {
301|     ctx.beginPath();
302|     ctx.moveTo(points[0][0], points[0][1]);
303|     for (let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
304|     ctx.closePath();
305|     ctx.fill();
306|   }
307| 
308|   function drawSea() {
309|     ctx.fillStyle = PAL.bg;
310|     ctx.fillRect(0, 0, W, H);
311| 
312|     // sea disc
313|     shadowedPath(() => {
314|       ctx.beginPath();
315|       ctx.arc(cx(), cy(), worldRadius() + 20, 0, Math.PI * 2);
316|       ctx.fill();
317|     }, '#3d405b');
318| 
319|     shadowedPath(() => {
320|       ctx.beginPath();
321|       ctx.arc(cx(), cy(), worldRadius() + 10, 0, Math.PI * 2);
322|       ctx.fill();
323|     }, '#5a6485');
324|   }
325| 
326|   function drawRocks() {
327|     const r = lighthouseRadius() * 1.35;
328|     const spikes = 14;
329|     const pts = [];
330|     for (let i = 0; i < spikes; i++) {
331|       const a = (i / spikes) * Math.PI * 2;
332|       const rad = r * (0.85 + (i % 2 === 0 ? 0.25 : 0));
333|       pts.push([cx() + Math.cos(a) * rad, cy() + Math.sin(a) * rad]);
334|     }
335|     shadowedPath(() => drawPolygon(jitterPolygon(pts, 2)), PAL.accent);
336|   }
337| 
338|   function drawBeam() {
339|     const beamWidth = 0.42;
340|     const len = worldRadius() + 30;
341|     ctx.save();
342|     ctx.globalAlpha = 0.35;
343|     ctx.fillStyle = '#f4e6b8';
344|     ctx.beginPath();
345|     ctx.moveTo(cx(), cy());
346|     ctx.arc(cx(), cy(), len, beamAngle - beamWidth, beamAngle + beamWidth);
347|     ctx.closePath();
348|     ctx.fill();
349|     ctx.restore();
350|   }
351| 
352|   function drawLighthouse() {
353|     const r = lighthouseRadius();
354|     // base tower - trapezoid built from jittered points
355|     const baseW = r * 0.9;
356|     const topW = r * 0.5;
357|     const topY = cy() - r * 2.4;
358|     const pts = [
359|       [cx() - baseW, cy() + r * 0.4],
360|       [cx() + baseW, cy() + r * 0.4],
361|       [cx() + topW, topY],
362|       [cx() - topW, topY]
363|     ];
364|     shadowedPath(() => drawPolygon(jitterPolygon(pts, 2)), PAL.layer);
365| 
366|     // stripes
367|     ctx.save();
368|     ctx.fillStyle = PAL.bg;
369|     for (let i = 0; i < 3; i++) {
370|       const t0 = 0.25 + i * 0.22;
371|       const y0 = cy() + r * 0.4 - (cy() + r*0.4 - topY) * t0;
372|       ctx.fillRect(cx() - baseW * (1 - t0*0.4), y0, (baseW * (1-t0*0.4))*2, 8);
373|     }
374|     ctx.restore();
375| 
376|     // lamp room
377|     shadowedPath(() => {
378|       ctx.beginPath();
379|       ctx.arc(cx(), topY - 6, r * 0.55, 0, Math.PI * 2);
380|       ctx.fill();
381|     }, PAL.accent);
382|     shadowedPath(() => {
383|       ctx.beginPath();
384|       ctx.arc(cx(), topY - 6, r * 0.35, 0, Math.PI * 2);
385|       ctx.fill();
386|     }, PAL.highlight);
387| 
388|     // roof
389|     const roofPts = [
390|       [cx() - r * 0.6, topY - 6 - r*0.3],
391|       [cx() + r * 0.6, topY - 6 - r*0.3],
392|       [cx(), topY - 6 - r*1.1]
393|     ];
394|     shadowedPath(() => drawPolygon(jitterPolygon(roofPts, 1.5)), PAL.layer);
395|   }
396| 
397|   function drawBoat(boat) {
398|     if (boat.wrecked) return;
399|     const bx = cx() + Math.cos(boat.angle) * boat.dist;
400|     const by = cy() + Math.sin(boat.angle) * boat.dist + Math.sin(boat.wobble) * 3;
401| 
402|     ctx.save();
403|     ctx.translate(bx, by);
404|     const rot = boat.angle + Math.PI/2;
405|     ctx.rotate(rot * 0.15); // slight tilt, not full alignment
406| 
407|     const hullPts = [
408|       [-14, 4], [14, 4], [10, 10], [-10, 10]
409|     ];
410|     const fillColor = boat.saved ? PAL.highlight : PAL.layer;
411|     shadowedPath(() => drawPolygon(jitterPolygon(hullPts, 1.5)), fillColor);
412| 
413|     // sail
414|     const sailPts = [
415|       [0, 4], [0, -18], [10, 3]
416|     ];
417|     shadowedPath(() => drawPolygon(jitterPolygon(sailPts, 1)), PAL.accent);
418| 
419|     ctx.restore();
420| 
421|     // light meter ring if not saved
422|     if (!boat.saved) {
423|       const pct = Math.min(1, boat.lit / boat.needLight);
424|       ctx.save();
425|       ctx.strokeStyle = PAL.highlight;
426|       ctx.lineWidth = 3;
427|       ctx.beginPath();
428|       ctx.arc(bx, by, 20, -Math.PI/2, -Math.PI/2 + pct * Math.PI * 2);
429|       ctx.stroke();
430|       ctx.restore();
431|     } else {
432|       ctx.save();
433|       ctx.fillStyle = PAL.accent;
434|       ctx.font = 'bold 14px sans-serif';
435|       ctx.textAlign = 'center';
436|       ctx.fillText('⚓', bx, by - 22);
437|       ctx.restore();
438|     }
439|   }
440| 
441|   function drawPlate(text, subtext, y) {
442|     ctx.save();
443|     const pw = Math.min(W * 0.86, 480);
444|     const ph = subtext ? 120 : 90;
445|     const px = cx() - pw / 2;
446|     const py = y - ph / 2;
447|     ctx.shadowColor = 'rgba(61,64,91,0.35)';
448|     ctx.shadowBlur = 6;
449|     ctx.shadowOffsetY = 3;
450|     ctx.fillStyle = PAL.bg;
451|     roundRect(px, py, pw, ph, 14);
452|     ctx.fill();
453|     ctx.shadowBlur = 0;
454|     ctx.shadowOffsetY = 0;
455|     ctx.strokeStyle = PAL.accent;
456|     ctx.lineWidth = 2;
457|     roundRect(px, py, pw, ph, 14);
458|     ctx.stroke();
459| 
460|     ctx.fillStyle = PAL.accent;
461|     ctx.textAlign = 'center';
462|     ctx.font = 'bold 24px sans-serif';
463|     ctx.fillText(text, cx(), py + 40);
464|     if (subtext) {
465|       ctx.font = '16px sans-serif';
466|       ctx.fillText(subtext, cx(), py + 72);
467|     }
468|     ctx.restore();
469|   }
470| 
471|   function roundRect(x, y, w, h, r) {
472|     ctx.beginPath();
473|     ctx.moveTo(x + r, y);
474|     ctx.lineTo(x + w - r, y);
475|     ctx.arcTo(x + w, y, x + w, y + r, r);
476|     ctx.lineTo(x + w, y + h - r);
477|     ctx.arcTo(x + w, y + h, x + w - r, y + h, r);
478|     ctx.lineTo(x + r, y + h);
479|     ctx.arcTo(x, y + h, x, y + h - r, r);
480|     ctx.lineTo(x, y + r);
481|     ctx.arcTo(x, y, x + r, y, r);
482|     ctx.closePath();
483|   }
484| 
485|   function draw() {
486|     drawSea();
487| 
488|     if (state === 'title') {
489|       drawLighthouse();
490|       drawPlate('Le Phare des Naufrages', 'Touchez et glissez pour tourner le faisceau — sauvez les bateaux !', cy());
491|       return;
492|     }
493| 
494|     drawRocks();
495|     drawBeam();
496|     drawLighthouse();
497|     for (const boat of boats) drawBoat(boat);
498| 
499|     // HUD text as canvas-drawn plate at top
500|     ctx.save();
501|     ctx.fillStyle = PAL.accent;
502|     ctx.font = 'bold 16px sans-serif';
503|     ctx.textAlign = 'left';
504|     ctx.fillText(stageGoalText, 14, 26);
505|     ctx.textAlign = 'right';
506|     ctx.fillText('Score: ' + score, W - 14, 26);
507|     ctx.restore();
508| 
509|     if (graceTimer > 0 && state === 'playing') {
510|       ctx.save();
511|       ctx.fillStyle = PAL.accent;
512|       ctx.font = 'bold 14px sans-serif';
513|       ctx.textAlign = 'center';
514|       ctx.fillText('Préparez-vous...', cx(), 52);
515|       ctx.restore();
516|     }
517| 
518|     if (state === 'stageclear') {
519|       drawPlate('Nuit ' + stage + ' réussie !', 'Prochaine nuit à venir...', cy());
520|     }
521|     if (state === 'win') {
522|       drawPlate('Toutes les nuits sont sauvées !', 'Touchez l\'écran pour recommencer', cy());
523|     }
524|     if (state === 'lose') {
525|       drawPlate('Un bateau s\'est brisé sur les rochers...', 'Touchez l\'écran pour recommencer', cy());
526|     }
527| 
528|     if (paused && state === 'playing') {
529|       drawPlate('Pause', '', cy());
530|     }
531|   }
532| 
533|   // ---- Host messages ----
534|   window.addEventListener('message', (event) => {
535|     const data = event.data;
536|     if (!data || data.source !== 'cartridge-host') return;
537|     if (data.type === 'pause') paused = true;
538|     if (data.type === 'resume') paused = false;
539|     if (data.type === 'reset') backToTitle();
540|   });
541| 
542|   // ---- Main loop ----
543|   function loop(now) {
544|     const dt = Math.min(0.05, (now - lastTime) / 1000);
545|     lastTime = now;
546|     update(dt);
547|     draw();
548|     if (!bootSent) {
549|       CARTRIDGE.send('boot', { title: 'Le Phare des Naufrages', gameType: 'stage-clear', lang: 'fr' });
550|       bootSent = true;
551|     }
552|     requestAnimationFrame(loop);
553|   }
554| 
555|   requestAnimationFrame(loop);
556| })();
557| </script>
558| </body>
559| </html>
560|

